<?php defined('ABSPATH') || exit; $company_id = absint($_GET['company'] ?? 0); $companies = get_posts(['post_type' => 'tj_company', 'numberposts' => -1, 'include' => $company_id ? [$company_id] : []]); ?>
<div class="tj-container"><?php tj_page_heading(tj_t('Công ty tuyển dụng IT', 'IT companies'), tj_t('Tìm hiểu đội ngũ trước khi bắt đầu hành trình mới.', 'Get to know your next team.')); ?><div class="tj-company-grid"><?php if (!$companies) { tj_empty(tj_t('Chưa có công ty để hiển thị.', 'No companies to display yet.')); } foreach ($companies as $company) { ?><article class="tj-panel"><span class="tj-company-mark"><?php echo esc_html(mb_substr(tj_title($company->ID), 0, 1)); ?></span><h2><?php echo esc_html(tj_title($company->ID)); ?></h2><p class="tj-muted"><?php echo esc_html(tj_meta($company->ID, 'location')); ?></p><div class="tj-prose"><?php echo wp_kses_post(wpautop(tj_content($company->ID))); ?></div><?php if (tj_meta($company->ID, 'website')) { ?><a target="_blank" rel="noopener noreferrer" href="<?php echo esc_url(tj_meta($company->ID, 'website')); ?>"><?php tj_e('Website công ty', 'Company website'); ?> ↗</a><?php } ?><p><a href="<?php echo esc_url(tj_url('viec-lam', ['q' => tj_title($company->ID)])); ?>"><?php tj_e('Xem việc làm', 'View jobs'); ?> →</a></p></article><?php } ?></div></div>
